<!--
 * 任务 DAG（列表页）
 *
 * @path apps\cronjob-web\src\views\job-dag\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 任务 DAG（列表页）
 * <p>消费后端契约 JobDagController（src/api/jobDag.ts，auto-generated by bash/gen-contract.py）：
 * 数据源 listEnabledDags()，支持启用 enableDag / 停用 disableDag（按 dagStatus 显示其一）、
 * 触发 triggerDag、删除 deleteDag、编辑/新增（jobDag-form.vue），
 * 以及版本管理：listDagVersions 抽屉展示版本记录 + rollbackDag 回滚。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeGridProps } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import { ElButton, ElDrawer, ElEmpty, ElMessage, ElMessageBox, ElTable, ElTableColumn, ElTag } from 'element-plus';
import { h, ref } from 'vue';
import { useI18n } from 'vue-i18n';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import {
  deleteDag,
  disableDag,
  enableDag,
  listDagVersions,
  listEnabledDags,
  rollbackDag,
  triggerDag,
} from '#/api/jobDag';
import type { JobDagVO, JobDagVersionVO } from '#/api/models';

import JobDagForm from './job-dag-form.vue';

defineOptions({ name: 'JobDagManagement' });
const { t } = useI18n();

/** 判断 DAG 是否为启用状态（兼容字符串/数字取值，未知值按启用处理） */
function isDagEnabled(dag: JobDagVO): boolean {
  const status = dag.dagStatus;
  return status === undefined || !(status === 'DISABLED' || status === 'PAUSED' || status === '0');
}

const gridOptions: VxeGridProps<JobDagVO> = {
  columns: [
    { type: 'seq', width: 50, title: t('common.seq') },
    { field: 'dagName', title: t('business.dagName'), width: 180 },
    { field: 'dagKey', title: 'DAG标识', width: 150 },
    {
      field: 'dagStatus',
      title: t('common.status'),
      width: 90,
      slots: {
        default: ({ row }) => {
          const dag = row as JobDagVO;
          return h(
            ElTag,
            { type: isDagEnabled(dag) ? 'success' : 'info' },
            () => (isDagEnabled(dag) ? '启用' : '停用'),
          );
        },
      },
    },
    { field: 'triggerType', title: '触发类型', width: 110 },
    { field: 'cronExpression', title: t('business.cronExpression'), width: 150 },
    { field: 'version', title: '版本', width: 80 },
    { field: 'description', title: '描述', width: 160 },
    { field: 'createdAt', title: t('common.createTime'), width: 160 },
    {
      field: 'action',
      title: t('common.actions'),
      width: 300,
      fixed: 'right',
      slots: {
        default: ({ row }) => {
          const dag = row as JobDagVO;
          return h('div', { class: 'flex gap-1' }, [
            h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => handleEdit(dag) }, () => t('common.edit')),
            isDagEnabled(dag)
              ? h(ElButton, { size: 'small', link: true, type: 'warning', onClick: () => handleDisable(dag) }, () => '停用')
              : h(ElButton, { size: 'small', link: true, type: 'success', onClick: () => handleEnable(dag) }, () => '启用'),
            h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => handleTrigger(dag) }, () => '触发'),
            h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => handleVersions(dag) }, () => '版本'),
            h(ElButton, { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(dag) }, () => t('common.delete')),
          ]);
        },
      },
    },
  ],
  height: 'auto',
  proxyConfig: {
    ajax: {
      query: async () => {
        const items = await listEnabledDags();
        return { items, total: items.length };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, zoom: true },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

const [JobDagFormModal, jobDagFormApi] = useYDSZModal({ connectedComponent: JobDagForm });

function handleAdd() {
  jobDagFormApi.open();
}

function handleEdit(row: JobDagVO) {
  jobDagFormApi.setData({ record: row });
  jobDagFormApi.open();
}

async function handleEnable(row: JobDagVO) {
  if (!row.id) return;
  try {
    await enableDag({ dagId: row.id });
    ElMessage.success('已启用');
    gridApi.query();
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

async function handleDisable(row: JobDagVO) {
  if (!row.id) return;
  try {
    await disableDag({ dagId: row.id });
    ElMessage.success('已停用');
    gridApi.query();
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

async function handleTrigger(row: JobDagVO) {
  if (!row.dagKey) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ElMessageBox.confirm(`确定立即触发DAG「${row.dagName}」吗？`, '触发确认', { type: 'warning' });
  } catch {
    return; // 用户主动取消触发操作
  }
  // 步骤2：执行触发 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await triggerDag({ dagKey: row.dagKey, triggerBy: 'console' });
    ElMessage.success('触发成功');
  } catch {
    // 错误已由请求拦截器展示，无需重复处理
  }
}

async function handleDelete(row: JobDagVO) {
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ElMessageBox.confirm(`确定删除DAG「${row.dagName}」吗？`, '删除确认', { type: 'warning' });
  } catch {
    return; // 用户主动取消删除操作
  }
  // 步骤2：执行删除 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    if (row.id) await deleteDag({ dagId: row.id });
    ElMessage.success('删除成功');
    gridApi.query();
  } catch {
    // 错误已由请求拦截器展示，无需重复处理
  }
}

/** 版本记录抽屉状态 */
const versionsDrawerVisible = ref(false);
const versions = ref<JobDagVersionVO[]>([]);
const currentDagId = ref('');

async function handleVersions(row: JobDagVO) {
  if (!row.id) return;
  currentDagId.value = row.id;
  versionsDrawerVisible.value = true;
  try {
    versions.value = await listDagVersions({ dagId: row.id });
  } catch {
    versions.value = [];
    // 错误提示由请求拦截器统一处理
  }
}

async function handleRollback(versionRow: JobDagVersionVO) {
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await ElMessageBox.confirm(
      `确定将DAG回滚到版本 v${versionRow.version ?? ''} 吗？`,
      '回滚确认',
      { type: 'warning' },
    );
  } catch {
    return; // 用户主动取消回滚操作
  }
  // 步骤2：执行回滚 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    await rollbackDag({ dagId: currentDagId.value }, { version: versionRow.version });
    ElMessage.success('回滚成功');
    versionsDrawerVisible.value = false;
    gridApi.query();
  } catch {
    // 错误已由请求拦截器展示，无需重复处理
  }
}
</script>

<template>
  <Page auto-content-height>
    <Grid :table-title="t('page.dag')">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleAdd">{{ t('common.create') }}</ElButton>
      </template>
    </Grid>
    <JobDagFormModal @success="gridApi.query()" />
    <ElDrawer v-model="versionsDrawerVisible" :title="t('page.dagList')" size="60%">
      <ElTable :data="versions" border>
        <ElTableColumn prop="version" label="版本" width="80" />
        <ElTableColumn prop="dagName" :label="t('business.dagName')" width="160" />
        <ElTableColumn prop="dagKey" label="标识" width="160" />
        <ElTableColumn prop="triggerType" label="触发类型" width="120" />
        <ElTableColumn prop="cronExpression" label="Cron" width="140" />
        <ElTableColumn prop="remark" label="备注" min-width="120" />
        <ElTableColumn prop="createdAt" :label="t('common.createTime')" width="170" />
        <ElTableColumn :label="t('common.actions')" width="100" fixed="right">
          <template #default="{ row }">
            <ElButton size="small" link type="primary" @click="handleRollback(row as JobDagVersionVO)">
              回滚
            </ElButton>
          </template>
        </ElTableColumn>
      </ElTable>
      <ElEmpty v-if="versions.length === 0" :description="t('common.noData')" />
    </ElDrawer>
  </Page>
</template>